/**
 * 기준일자 지정검색 
 */
scwin.fn_list_sync = function() {
    /*
    if ( getObjectValue(edt_BASE_DD) > cGetToday("yyyymmdd")) {
    	alert("기준일이 현재일보다 큽니다.");
    	edt_BASE_DD.focus();
    	return;
    }
    */

    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=ETN_LSTISUDTLSRCH_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.etn.lstsrch.lstDtlSrch_basedt.list" + "&{P}param00=" + $c.stf.getObjectValue(edt_BASE_DD) + "&{P}param01=" + $c.stf.getObjectValue(edt_BASE_DD) + "&{P}param02=" + $c.stf.getObjectValue(cmb_ETP_PROD_TP_CD) + "&{P}param03=" + $c.stf.getObjectValue(cmb_ETP_PROD_TP_CD) + "&{P}param04=" + $c.stf.getObjectValue(cmb_IDX_CALC_INST_CD) + "&{P}param05=" + $c.stf.getObjectValue(cmb_IDX_CALC_INST_CD) + "&{P}param06=" + $c.stf.getObjectValue(cmb_BAS_IDX_CD) + "&{P}param07=" + $c.stf.getObjectValue(cmb_BAS_IDX_CD) + "&{P}param08=" + $c.stf.getObjectValue(cmb_IDX_MKT_CLSS_CD_01) + "&{P}param09=" + $c.stf.getObjectValue(cmb_IDX_MKT_CLSS_CD_01) + "&{P}param10=" + $c.stf.getObjectValue(cmb_IDX_MKT_CLSS_CD_02) + "&{P}param11=" + $c.stf.getObjectValue(cmb_IDX_MKT_CLSS_CD_02) + "&{P}param12=" + $c.stf.getObjectValue(cmb_IDX_MKT_CLSS_CD_03) + "&{P}param13=" + $c.stf.getObjectValue(cmb_IDX_MKT_CLSS_CD_03) +
        //기초자산구분(대)
        "&{P}param14=" + $c.stf.getObjectValue(cmb_IDX_ASST_CLSS_ID1_01) + "&{P}param15=" + $c.stf.getObjectValue(cmb_IDX_ASST_CLSS_ID1_01) + "&{P}param16=" + $c.stf.getObjectValue(cmb_IDX_ASST_CLSS_ID1_01) +
        //기초자산구분(중)
        "&{P}param17=" + $c.stf.getObjectValue(cmb_IDX_ASST_CLSS_ID1_02) + "&{P}param18=" + $c.stf.getObjectValue(cmb_IDX_ASST_CLSS_ID1_02) + "&{P}param19=" + $c.stf.getObjectValue(cmb_IDX_ASST_CLSS_ID1_02) +
        //기조차산구분(소)
        "&{P}param20=" + $c.stf.getObjectValue(cmb_IDX_ASST_CLSS_ID1_03) + "&{P}param21=" + $c.stf.getObjectValue(cmb_IDX_ASST_CLSS_ID1_03) + "&{P}param22=" + $c.stf.getObjectValue(cmb_IDX_ASST_CLSS_ID1_03) + "&{P}param23=" + $c.stf.getObjectValue(cmb_ETF_REPLICA_METHD_TP_CD) + "&{P}param24=" + $c.stf.getObjectValue(cmb_ETF_REPLICA_METHD_TP_CD) + "&{P}param25=" + $c.stf.getObjectValue(cmb_IDX_LVRG_INVRS_TP_CD) + "&{P}param26=" + $c.stf.getObjectValue(cmb_IDX_LVRG_INVRS_TP_CD) + "&{P}param27=" + $c.stf.getObjectValue(cmb_EARNG_STRUCT_TP_CD) + "&{P}param28=" + $c.stf.getObjectValue(cmb_EARNG_STRUCT_TP_CD) + "&{P}param29=" + $c.stf.getObjectValue(cmb_LIST_STAT_CD) + "&{P}param30=" + $c.stf.getObjectValue(cmb_LIST_STAT_CD);

    //alert(url);


    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List); // 그리드명을 표기		

};


/**
 *  검색 조건 콤보박스 
 */
scwin.fn_SetCode = function() {
    var strCbd = "",
        i, j;

    //기초지수
    var urlBas = "/listingCommon.do";
    urlBas += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    urlBas += "&method=listGeneral" + "&outputMessageId=ETN_LSTISUDTLSRCH_OUT_COMBO" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.etn.lstsrch.basIdxCd.list";
    dst_BAS_IDX_CD.DataID = encodeURI(urlBas);
    dst_BAS_IDX_CD.reset();
    strCbd = "^전체";
    cmb_BAS_IDX_CD.CBData = strCbd;
    /*
		for (j = 1; j <= dst_BAS_IDX_CD.CountRow; j++) {
			strCbd +=  (strCbd == "" ? "" : ",") + dst_BAS_IDX_CD.NameValue(j, "VALUE") + "^" + dst_BAS_IDX_CD.NameValue(j, "TEXT");
		}
	    */
    cmb_BAS_IDX_CD.CBData = strCbd;


    //시장구분		
    var urlMkt = "/listingCommon.do";
    urlMkt += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    urlMkt += "&method=listGeneral" + "&outputMessageId=ETN_LSTISUDTLSRCH_OUT_COMBO" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.etn.lstsrch.idxMktClss.list";
    dst_IDX_MKT_CLSS.DataID = encodeURI(urlMkt);
    dst_IDX_MKT_CLSS.reset();
    strCbd = "^전체";
    cmb_IDX_MKT_CLSS_CD_01.CBData = strCbd;
    cmb_IDX_MKT_CLSS_CD_02.CBData = strCbd;
    cmb_IDX_MKT_CLSS_CD_03.CBData = strCbd;
    for (j = 1; j <= dst_IDX_MKT_CLSS.getTotalRow(); j++) {
        if (dst_IDX_MKT_CLSS.getCellData(j, "PVALUE") == "") {
            strCbd = strCbd + (strCbd == "" ? "" : ",") + dst_IDX_MKT_CLSS.getCellData(j, "VALUE") + "^" + dst_IDX_MKT_CLSS.getCellData(j, "TEXT");
        }
    }
    //alert("strCbd="+strCbd);
    cmb_IDX_MKT_CLSS_CD_01.CBData = strCbd;

    //기초자산구분
    var urlAsst = "/listingCommon.do";
    urlAsst += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    urlAsst += "&method=listGeneral" + "&outputMessageId=ETN_LSTISUDTLSRCH_OUT_COMBO" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.etn.lstsrch.idxAsstClss.list";
    dst_IDX_ASST_CLSS.DataID = encodeURI(urlAsst);
    dst_IDX_ASST_CLSS.reset();
    strCbd = "^전체";
    cmb_IDX_ASST_CLSS_ID1_01.CBData = strCbd;
    cmb_IDX_ASST_CLSS_ID1_02.CBData = strCbd;
    cmb_IDX_ASST_CLSS_ID1_03.CBData = strCbd;
    for (j = 1; j <= dst_IDX_ASST_CLSS.getTotalRow(); j++) {
        if (dst_IDX_ASST_CLSS.getCellData(j, "PVALUE") == "") {
            strCbd += (strCbd == "" ? "" : ",") + dst_IDX_ASST_CLSS.getCellData(j, "VALUE") + "^" + dst_IDX_ASST_CLSS.getCellData(j, "TEXT");
        }
    }
    cmb_IDX_ASST_CLSS_ID1_01.CBData = strCbd;
};



/**
 *  검색 조건 콤보박스 
 */
scwin.fn_searchCode = function() {
    /*
    상품유형 			ETP_PROD_TP_CD
    지수산출기관 	IDX_CALC_INST_CD
    레버리지				IDX_LVRG_INVRS_TP_CD
    복제방법				ETF_REPLICA_METHD_TP_CD
    */
    var arrCid = [{
        cid: "ETP_PROD_TP_CD",
        cnm: "cmb_ETP_PROD_TP_CD"
    }, {
        cid: "IDX_CALC_INST_CD",
        cnm: "cmb_IDX_CALC_INST_CD"
    }, {
        cid: "IDX_LVRG_INVRS_TP_CD",
        cnm: "cmb_IDX_LVRG_INVRS_TP_CD"
    }, {
        cid: "ETF_REPLICA_METHD_TP_CD",
        cnm: "cmb_ETF_REPLICA_METHD_TP_CD"
    }, {
        cid: "LOSS_LMT_ETN_EARNG_STRUCT_CD",
        cnm: "cmb_EARNG_STRUCT_TP_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='ETP_PROD_TP_CD','IDX_CALC_INST_CD','IDX_LVRG_INVRS_TP_CD','ETF_REPLICA_METHD_TP_CD','LOSS_LMT_ETN_EARNG_STRUCT_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "^전체";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};




/**
 * 표출 항목 체크박스 이벤트 처리 
 */
scwin.fn_chk_onclick = function(columnId) {
    var isView = $c.cm.getColumnProp(grd_List, columnId, "Show");
    if (isView) {
        $c.cm.setColumnProp(grd_List, columnId, "Show", "false");
    }
    if (isView == "FALSE") {
        $c.cm.setColumnProp(grd_List, columnId, "Show", "true");
    }
};



/**
 * 상위-하위 콤보박스 값 연동 
 */
scwin.fn_OnStepComboSelChange = function(pValue, dst, targetObj, targetPValueNm) {
    var strCbd = "^전체";
    targetObj.CBData = strCbd;
    if (!(pValue == "" || pValue == null)) {
        for (j = 1; j <= dst.getTotalRow(); j++) {
            //alert(dst.NameValue(j, "TEXT")) ;
            if (dst.getCellData(j, targetPValueNm) == pValue) {
                strCbd += (strCbd == "" ? "" : ",") + dst.getCellData(j, "VALUE") + "^" + dst.getCellData(j, "TEXT");
            }
        }
        targetObj.CBData = strCbd;
        targetObj.ResetData();
        //alert( "CountRow="+targetObj.CountRow) ;

    }
};






/**
 *  상품유형 선택 시
 */
scwin.fn_changeETP_PROD_TP_CD = function() {
    var vETP_PROD_TP_CD = $c.stf.getObjectValue(cmb_ETP_PROD_TP_CD);
    if (vETP_PROD_TP_CD == '4') {
        //손실제한 ETN 선택 시
        cmb_EARNG_STRUCT_TP_CD.setDisabled(false); //수익구조유형

    } else {
        cmb_EARNG_STRUCT_TP_CD.setDisabled(true);
        $c.stf.setObjectValue(cmb_EARNG_STRUCT_TP_CD, "전체");
    }
};
scwin.fn_init = function() {
    scwin.fn_changeETP_PROD_TP_CD();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List); //데이터 로딩중닫기 및 조회없음 처리		

};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.img_BASE_DD_onclick = function() {
    popUpCalendar2(edt_BASE_DD);
};
scwin.dts_small_ind_OnFilter = function(row) {
    //  중분류에 해당하는 소분류를 보여준다.
    if (gInd == "%") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        var s_ind = dts_small_ind.getCellData(row, "VALUE");
        //alert(s_ind);
        if (s_ind.substring(0, 4) == gInd || dts_small_ind.getCellData(row, "VALUE") == "%") {
            return true;
        } else {
            return false;
        }
    }
};
