scwin.gform_onload = function() {
    edt_BASE_DD.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    //round처리
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    scwin.fn_SetCode();
    scwin.fn_searchCode();
    scwin.fn_init();

    //초기로딩시 3개 칼럼만 표시한다.

};
